<?php namespace Tests\Feature; use App\Models\Project; use App\Models\ProjectMember; use App\Models\Sprint; use App\Models\User; use Illuminate\Foundation\Testing\RefreshDatabase; use Tests\TestCase; class SprintTest extends TestCase { use RefreshDatabase; public function test_sprint_model_can_be_created(): void { $this->seed(); $manager = User::factory()->create(); $manager->givePermissionTo(["project.manage"]); $project = Project::create(["key" => "HEL", "name" => "Helpdesk", "owner_id" => $manager->id]); ProjectMember::create(["project_id" => $project->id, "user_id" => $manager->id, "role" => ProjectMember::ROLE_LEAD]); $sprint = Sprint::create(["project_id" => $project->id, "name" => "S1", "ends_at" => now()]); $this->assertDatabaseHas("sprints", ["project_id" => $project->id, "name" => "S1"]); } }
